----CONFIG-TYPES
import uPlot, { Axis as UAxis, Hooks, Series, Options, Plugin, Band } from 'uplot';
import Yagr, { YagrMeta, YagrState } from './index';
import { TooltipOptions } from './plugins/tooltip/types';
import { LegendOptions } from './plugins/legend/legend';
import { CursorOptions } from './plugins/cursor/cursor';
import { PlotLineOptions } from './plugins/plotLines/plotLines';
type AllSeriesOptions = ExtendedSeriesOptions & CommonSeriesOptions & Omit<DotsSeriesOptions, 'type'> & Omit<LineSeriesOptions, 'type'> & Omit<AreaSeriesOptions, 'type'> & Omit<ColumnSeriesOptions, 'type'>;
declare module 'uplot' {
    interface Series extends Omit<AllSeriesOptions, 'data'> {
        id: string;
        color: string;
        name: string;
        /** Assigned by Yagr to uPlot series */
        data: DataSeriesExtended;
        /** Will appear after processing series */
        $c: DataSeriesExtended;
        /** Will appear after processing series if serie values normalized */
        normalizedData?: DataSeries;
        /** Does line have only null values */
        empty?: boolean;
        /** Real values count */
        count: number;
        /** Values sum */
        sum: number;
        /** Average value */
        avg: number;
        /** Get focus color */
        getFocusedColor: (y: Yagr, idx: number) => string;
        /** Current focus state */
        _focus?: boolean | null;
        /** Is series data transformd */
        _transformed?: boolean;
        /** Temporary hidden flag for showInGraph */
        _tempHidden?: boolean;
    }
    interface Axis {
        getFormatter?: (range: number) => (value: number) => string;
    }
}
/**
 * Main Yagr chart config
 */
export interface YagrConfig {
    /** Main chart visualization config */
    chart: YagrChartOptions;
    /** Graph title style. To customize other properties use CSS */
    title: {
        text: string;
        fontSize?: number;
    };
    /** Chart inline legend configuration */
    legend: LegendOptions;
    /** Config for axes. Determines style and labeling */
    axes: Record<string, AxisOptions>;
    /** Options for cursor plugin. Determines style, visibility and points render */
    cursor: CursorOptions;
    /** Timestamps */
    timeline: number[];
    /** Tooltip config. Detemines tooltip's behavior */
    tooltip: Partial<TooltipOptions>;
    /** Grid options (applies to all axes, can be overrided by axis.grid). */
    grid: UAxis.Grid;
    /** Marker visualisation options */
    markers: MarkersOptions;
    /** Scales options */
    scales: Record<string, Scale>;
    /** PlotLines plugin options */
    plotLines: PlotLineOptions;
    /** Raw series data and options */
    series: RawSerieData[];
    /** UPlot bands for grouping series*/
    bands?: Band[];
    /** uPlot hooks + Yagr hooks */
    hooks: YagrHooks;
    /** Yagr data processing options */
    processing?: ProcessingSettings;
    /** uPlot options transform method */
    editUplotOptions?: (opts: Options) => Options;
    /** Additional Yagr plugins */
    plugins: Record<string, YagrPlugin>;
}
export type MinimalValidConfig = Partial<YagrConfig> & {
    timeline: Number[];
    series: RawSerieData[];
};
type CommonHookHandlerArg<T> = T & {
    chart: Yagr;
};
export type HookHandler<Data> = ((a: CommonHookHandlerArg<Data>) => void)[];
export type LoadHandlerArg = CommonHookHandlerArg<{
    meta: YagrMeta;
}>;
export type OnSelectHandlerArg = CommonHookHandlerArg<{
    from: number;
    to: number;
}>;
export type ErrorHandlerArg = CommonHookHandlerArg<{
    type: YagrState['stage'];
    error: Error;
}>;
export type ProcessedHandlerArg = CommonHookHandlerArg<{
    meta: Pick<YagrMeta, 'processTime'>;
}>;
export type InitedHandlerArg = CommonHookHandlerArg<{
    meta: Pick<YagrMeta, 'initTime'>;
}>;
export type DisposeHandlerArg = CommonHookHandlerArg<{}>;
export type ResizeHandlerArg = CommonHookHandlerArg<{
    entries: ResizeObserverEntry[];
}>;
export type ScaleUpdateHandlerArg = CommonHookHandlerArg<{
    scales: Record<string, {
        min: number;
        max: number;
    }>;
}>;
export interface InternalYargHooks {
    load?: HookHandler<{
        meta: YagrMeta;
    }>;
    onSelect?: HookHandler<{
        from: number;
        to: number;
    }>;
    error?: HookHandler<{
        error: Error;
        stage: YagrState['stage'];
    }>;
    processed?: HookHandler<{
        meta: Pick<YagrMeta, 'processTime'>;
    }>;
    inited?: HookHandler<{
        meta: Pick<YagrMeta, 'initTime'>;
