        const {values} = source.getHistory();
        return values.length ? values[values.length - 1] : null;
    });

    React.useEffect(() => source.subscribe((point) => setValue(point.value)), [source]);

    if (value === null) {
        return <Label theme="unknown">нет данных</Label>;
